        build(envelope,frame);eq(envelope,"backend_id","ck3-"+frame.build().version()+"-native-"+kind.suffix);eq(envelope,"domain_key",kind.domain());eq(envelope,"snapshot_revision",frame.nativeRevision());eq(envelope,"date_raw",frame.date());
